study/querydsl/entity/QMember.java

package study.querydsl.entity;

import static com.querydsl.core.types.PathMetadataFactory.*;

import com.querydsl.core.types.dsl.*;
import com.querydsl.core.types.PathMetadata;
import jakarta.annotation.Generated;
import com.querydsl.core.types.Path;
import com.querydsl.core.types.dsl.PathInits;

@Generated("com.querydsl.codegen.DefaultEntitySerializer")
public class QMember extends EntityPathBase<Member> {

    private static final long serialVersionUID = 1234567890L;

    private static final PathInits INITS = PathInits.DIRECT2;

    public static final QMember member = new QMember("member1");

    public final NumberPath<Integer> age = createNumber("age", Integer.class);

    public final NumberPath<Long> id = createNumber("id", Long.class);

    public final QTeam team;

    public final StringPath username = createString("username", String.class);

    public QMember(String variable) {
        this(Member.class, forVariable(variable), INITS);
    }

    public QMember(Path<? extends Member> path) {
        this(path.getType(), path.getMetadata(), PathInits.getFor(
                path.getMetadata(), INITS));
    }

    public QMember(PathMetadata metadata, PathInits inits) {
        this(Member.class, metadata, inits);
    }

    public QMember(Class<? extends Member> type, PathMetadata metadata,
                   PathInits inits) {
        super(type, metadata, inits);
        this.team = inits.isInitialized("team")
                ? new QTeam(forProperty("team")) : null;
    }
}

--   jakarta.annotation.Generated 가 보인다
--   2.1절에서 이걸 넣은 이유다
--   team 은 조건부로 만들어진다


-- 필드 타입이 메서드를 정한다

@Test
void 경로_타입() {
    System.out.println("username: " + member.username.getClass().getSimpleName());
    System.out.println("age:      " + member.age.getClass().getSimpleName());
    System.out.println("team:     " + member.team.getClass().getSimpleName());
}

username: StringPath
age:      NumberPath
team:     QTeam

